// Complete native assemblies. No artwork is synthesised or rescaled.
const copy=v=>structuredClone(v);
const uid=()=>globalThis.crypto?.randomUUID?.()||'assembly-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const inside=(r,x,y)=>x>=r.x&&y>=r.y&&x<r.x+r.w&&y<r.y+r.h;
const overlap=(a,b)=>a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
const signature=v=>JSON.stringify(v??null);
export function assemblyAt(map,x,y){return(map.nativeAssemblies||[]).find(a=>a.locked!==false&&inside(a,x,y));}
export function assertObjectPlacement(map,r,{allowTreeCanopies=false}={}){if(map.objects.some(o=>o.id!==r.id&&overlap(r,o)&&((!allowTreeCanopies&&!r.tree&&o.tree)||(r.tree&&!o.tree))))throw Error('This would cut through a complete tree. Move or erase the tree first.');if(r.x<0||r.y<0||r.x+r.w>map.width||r.y+r.h>map.height)throw Error('The complete object must fit inside the map.');if((map.nativeAssemblies||[]).some(a=>a.locked!==false&&overlap(r,a)))throw Error('This overlaps a protected ROM object. Move or unlock it first.');}
export function assertAssemblyEdit(map,x,y){const a=assemblyAt(map,x,y);if(a)throw Error(a.name+' is a complete object. Move, remove or unlock it in Objects → ROM objects before editing its tiles or rules.');}
export function assemblyCompatibility(map,template){return !!map.rom&&(template.overlay?map.rom.metatileLayers===template.layerCount:map.rom.sourceId===template.sourceId&&map.rom.layerAtlasIds?.length===template.layerCount&&map.rom.atlasId===template.atlasId);}
export function captureNativeAssembly(map,rect,{id,name='ROM object',category='Other',sourceKey=map.rom?.key||map.rom?.templateKey,entrances=[]}={}){
 const {x,y,w,h}=rect;if(!map.rom?.nativeLayerSplit||![x,y,w,h].every(Number.isInteger)||w<1||h<1||w>64||h>64||x<0||y<0||x+w>map.width||y+h>map.height)throw Error('Select a complete rectangle inside a map imported with native layers.');
 if(map.objects.some(o=>overlap(rect,o))||(map.wallCells||[]).some((v,i)=>v&&inside(rect,i%map.width,Math.floor(i/map.width))))throw Error('This area contains placed objects or walls. Capture the source tiles before adding cutouts or walls.');
 const layers=Object.fromEntries(['ground','details','objects','overhead'].map(k=>[k,[]])),rules=[];
 for(let dy=0;dy<h;dy++)for(let dx=0;dx<w;dx++){
  const i=(y+dy)*map.width+x+dx;for(const k of Object.keys(layers))layers[k].push(copy(map.layers[k]?.[i]??null));
  const sourceIndex=map.rom.sourceCells?map.rom.sourceCells[i]:i,word=sourceIndex===null?0:map.rom.originalBlocks?.[sourceIndex]??0,tile=map.layers.ground[i],tileId=tile?Math.floor(tile.sy/16)*16+Math.floor(tile.sx/16):word&1023,attr=map.rom.attributes?.[tileId]||0;
  rules.push(copy(map.movement?.[i]||tile?.nativeRule||{mode:word&0xc00?'block':(attr&511)===16?'water':'walk',collision:word>>>10&3,elevation:word>>>12&15,behavior:attr&(map.rom.engine==='frlg'?511:255),layerType:map.rom.engine==='frlg'?(attr>>>29)&3:(attr>>>12)&15}));
 }
 return{id:id||uid(),name,category,w,h,layers,rules,entrances:copy(entrances),sourceId:map.rom.sourceId,sourceKey,atlasId:map.rom.atlasId,layerCount:map.rom.metatileLayers||2,sourceRect:{...rect}};
}
export function planAssembly(project,map,t,x,y,{ignoreId=null,allowSourceEvents=false}={}){
 if(!assemblyCompatibility(map,t))throw Error('This object belongs to a different ROM tileset or palette. Choose a matching map or import its source map.');
 const r={x,y,w:t.w,h:t.h};if(![x,y].every(Number.isInteger)||x<0||y<0||x+t.w>map.width||y+t.h>map.height)throw Error('The whole '+t.name+' must fit inside the map.');
 if((map.nativeAssemblies||[]).some(a=>a.id!==ignoreId&&overlap(r,a))||map.objects.some(o=>overlap(r,o)))throw Error('This space overlaps another complete object. Move it first.');
 const occupied=[...map.markers,...map.fieldObjects||[],...map.gates||[]];if(occupied.some(p=>inside(r,p.x,p.y)))throw Error('This space contains an NPC, event, sign or HM object. Move it first.');
 for(const l of project.links)if(l.assemblyId!==ignoreId&&['from','to'].some(k=>l[k].mapId===map.id&&inside(r,l[k].x,l[k].y)))throw Error('This space contains a map entrance or connection. Move it first.');
 if(!allowSourceEvents&&!map.rom.generated)for(const events of Object.values(map.rom.events||{}))if(Array.isArray(events)&&events.some(p=>inside(r,p.x-(map.rom.cropOffset?.x||0),p.y-(map.rom.cropOffset?.y||0))))throw Error('This space contains an original ROM event. Choose clear tiles.');
 return r;
}
function snapshot(map,r){return{layers:Object.fromEntries(Object.keys(map.layers).map(k=>[k,Array.from({length:r.w*r.h},(_,i)=>copy(map.layers[k][(r.y+Math.floor(i/r.w))*map.width+r.x+i%r.w]))])),movement:Array.from({length:r.w*r.h},(_,i)=>copy(map.movement?.[(r.y+Math.floor(i/r.w))*map.width+r.x+i%r.w]??null))};}
function write(map,r,data){map.movement??=Array(map.width*map.height).fill(null);for(let i=0;i<r.w*r.h;i++){const j=(r.y+Math.floor(i/r.w))*map.width+r.x+i%r.w;for(const k of Object.keys(map.layers))map.layers[k][j]=copy(data.layers[k]?.[i]??null);map.movement[j]=copy(data.rules?.[i]??data.movement?.[i]??null);}}
export function placeAssembly(project,map,t,x,y,options={}){const r=planAssembly(project,map,t,x,y,options),a={id:uid(),templateId:t.id,name:t.name,...r,locked:true,before:snapshot(map,r),expected:{layers:copy(t.layers),rules:copy(t.rules)},entrances:copy(t.entrances||[])};if(t.overlay){a.overlay=copy(t.overlay);a.sourceRules=copy(t.rules);a.expected.layers=copy(a.before.layers);a.expected.rules=t.rules.map((v,i)=>t.overlay.mask[i]?copy(v):copy(a.before.movement[i]));}write(map,r,a.expected);(map.nativeAssemblies??=[]).push(a);return a;}
export function removeAssembly(map,id){const a=map.nativeAssemblies?.find(a=>a.id===id);if(!a)return;write(map,a,a.before);map.nativeAssemblies=map.nativeAssemblies.filter(v=>v.id!==id);}
export function moveAssembly(project,map,id,x,y){const a=map.nativeAssemblies?.find(a=>a.id===id);if(!a)throw Error('Object no longer exists.');if(x===a.x&&y===a.y)return a;if(a.locked===false)throw Error('This assembly was unlocked for tile edits. Save it as a new complete object before moving it.');if(overlap(a,{x,y,w:a.w,h:a.h}))throw Error('Move the object to a clear space outside its current footprint.');const t={...a.expected,...(a.overlay?{overlay:copy(a.overlay),rules:copy(a.sourceRules)}:{}),id:a.templateId,name:a.name,w:a.w,h:a.h,entrances:a.entrances,sourceId:map.rom.sourceId,atlasId:map.rom.atlasId,layerCount:map.rom.metatileLayers||2};planAssembly(project,map,t,x,y,{ignoreId:id});removeAssembly(map,id);const n=placeAssembly(project,map,t,x,y);n.id=id;if(a.interiorId)n.interiorId=a.interiorId;for(const l of project.links.filter(l=>l.assemblyId===id))for(const k of ['from','to'])if(l[k].mapId===map.id){l[k].x+=x-a.x;l[k].y+=y-a.y;}return n;}
export function assemblyFindings(map){const out=[];for(const a of map.nativeAssemblies||[]){if(a.x<0||a.y<0||a.x+a.w>map.width||a.y+a.h>map.height){out.push({severity:'error',x:a.x,y:a.y,message:a.name+' is cut off by the map edge.'});continue;}if(map.objects.some(o=>overlap(a,o))||(map.wallCells||[]).some((v,i)=>v&&inside(a,i%map.width,Math.floor(i/map.width))))out.push({severity:'error',x:a.x,y:a.y,message:a.name+' overlaps another object or wall.'});if(!a.locked){out.push({severity:'warning',x:a.x,y:a.y,message:a.name+' is unlocked; its tiles can be edited separately.'});continue;}for(let i=0;i<a.w*a.h;i++){const j=(a.y+Math.floor(i/a.w))*map.width+a.x+i%a.w;if(Object.keys(map.layers).some(k=>signature(map.layers[k][j])!==signature(a.expected.layers[k]?.[i]))||signature(map.movement?.[j])!==signature(a.expected.rules[i])){out.push({severity:'error',x:a.x+i%a.w,y:a.y+Math.floor(i/a.w),message:a.name+' has changed tiles, layering or movement rules. Restore or unlock the object.'});break;}}
 for(const e of a.entrances||[])out.push({severity:'warning',x:a.x+e.x,y:a.y+e.y,message:a.name+' entrance: check its interior link.'});}return out;}
export function validateAssemblies(project,assetIds){
 const checkOverlay=t=>{if(!t.overlay)return;const o=t.overlay;if(o.version!==2||!Array.isArray(o.planeAssetIds)||![2,3].includes(o.planeAssetIds.length)||o.planeAssetIds.some(id=>!assetIds.has(id))||!Array.isArray(o.mask)||o.mask.length!==t.w*t.h||o.mask.some(v=>typeof v!=='boolean'))throw Error('Invalid backgroundless ROM object.');};
 const check=t=>{if(!t||typeof t.id!=='string'||typeof t.name!=='string'||![t.w,t.h].every(n=>Number.isInteger(n)&&n>=1&&n<=64)||!t.layers||!Array.isArray(t.rules)||t.rules.length!==t.w*t.h||['ground','details','objects','overhead'].some(k=>!Array.isArray(t.layers[k])||t.layers[k].length!==t.w*t.h||t.layers[k].some(v=>v&&(!assetIds.has(v.a)||![v.sx,v.sy,v.size].every(Number.isFinite)))))throw Error('A complete ROM object has invalid tiles or rules.');};
 if(project.romObjects!==undefined&&(!Array.isArray(project.romObjects)||project.romObjects.length>512))throw Error('The ROM object collection is too large.');for(const t of project.romObjects||[]){check(t);checkOverlay(t);}
 for(const m of project.maps){if(m.nativeAssemblies!==undefined&&(!Array.isArray(m.nativeAssemblies)||m.nativeAssemblies.length>1000))throw Error('Too many complete objects on one map.');for(const a of m.nativeAssemblies||[]){checkOverlay(a);if(a.overlay&&(!Array.isArray(a.sourceRules)||a.sourceRules.length!==a.w*a.h))throw Error('Invalid object collision mask.');if(![a.x,a.y].every(Number.isInteger)||typeof a.locked!=='boolean'||!a.before||!Array.isArray(a.before.movement)||a.before.movement.length!==a.w*a.h||!a.expected)throw Error('Invalid placed ROM object.');check({...a.expected,id:a.id,name:a.name,w:a.w,h:a.h});check({...a.before,rules:a.before.movement,id:a.id,name:a.name,w:a.w,h:a.h});}}
}

export function refreshPlacedAssemblies(project,map){const replacements=(map.nativeAssemblies||[]).filter(a=>a.locked&&project.romObjects?.some(t=>t.id===a.templateId&&t.overlay?.version===2&&t.w===a.w&&t.h===a.h));for(const old of replacements){const t=project.romObjects.find(t=>t.id===old.templateId);removeAssembly(map,old.id);const next=placeAssembly(project,map,t,old.x,old.y,{ignoreId:old.id,allowSourceEvents:true});next.id=old.id;for(const l of project.links.filter(l=>l.assemblyId===old.id))for(const k of ['from','to'])if(l[k].mapId===map.id){const i=(old.entrances||[]).findIndex(e=>old.x+e.x===l[k].x&&old.y+e.y===l[k].y),e=t.entrances?.[i];if(e){l[k].x=next.x+e.x;l[k].y=next.y+e.y;}}if(old.interiorId)next.interiorId=old.interiorId;}return replacements.length;}
